({__plugin:null,__load(){if(this.__plugin)return this.__plugin;this.__plugin=function(){"use strict";let locales=unbound.i18n.createLocales({MOCK_DESC:"Sends your text in aLtErNaTiNg CaSe",UPSIDE_DESC:"Sends your text upside down",ZALGO_DESC:"Sends your text with Z̷a̸l̵g̶o̴ marks stacked on it",SMALLCAPS_DESC:"Sends your text in sᴍᴀʟʟ ᴄᴀᴘs",TEXT_DESC:"The text to restyle"});locales.messages,locales.format,locales.useMessages;var UPSIDE_DOWN={a:"ɐ",b:"q",c:"ɔ",d:"p",e:"ǝ",f:"ɟ",g:"ƃ",h:"ɥ",i:"ᴉ",j:"ɾ",k:"ʞ",l:"l",m:"ɯ",n:"u",o:"o",p:"d",q:"b",r:"ɹ",s:"s",t:"ʇ",u:"n",v:"ʌ",w:"ʍ",x:"x",y:"ʎ",z:"z",A:"∀",B:"ꓭ",C:"Ɔ",D:"ꓷ",E:"Ǝ",F:"Ⅎ",G:"ꓨ",H:"H",I:"I",J:"ſ",K:"ꓘ",L:"˥",M:"W",N:"N",O:"O",P:"Ԁ",Q:"Ό",R:"ꓤ",S:"S",T:"⊥",U:"∩",V:"Λ",W:"M",X:"X",Y:"⅄",Z:"Z",0:"0",1:"Ɩ",2:"ᄅ",3:"Ɛ",4:"ㄣ",5:"ϛ",6:"9",7:"ㄥ",8:"8",9:"6",".":"˙",",":"'","'":",",'"':"„","?":"\xbf","!":"\xa1","(":")",")":"(","[":"]","]":"[","{":"}","}":"{","<":">",">":"<",_:"‾","&":"⅋",";":"؛"},SMALL_CAPS={a:"ᴀ",b:"ʙ",c:"ᴄ",d:"ᴅ",e:"ᴇ",f:"ꜰ",g:"ɢ",h:"ʜ",i:"ɪ",j:"ᴊ",k:"ᴋ",l:"ʟ",m:"ᴍ",n:"ɴ",o:"ᴏ",p:"ᴘ",q:"ǫ",r:"ʀ",s:"s",t:"ᴛ",u:"ᴜ",v:"ᴠ",w:"ᴡ",x:"x",y:"ʏ",z:"ᴢ"},ZALGO_MARKS=[...Array.from({length:112},(_,index)=>String.fromCodePoint(768+index))];function mock(text){var upper=!1;return Array.from(text).map(character=>character.toLowerCase()===character.toUpperCase()?character:(upper=!upper)?character.toLowerCase():character.toUpperCase()).join("")}function upsideDown(text){return Array.from(text).reverse().map(character=>UPSIDE_DOWN[character]??character).join("")}function smallCaps(text){return Array.from(text.toLowerCase()).map(character=>SMALL_CAPS[character]??character).join("")}function zalgo(text,intensity=6,random=Math.random){var characters=Array.from(text),letters=characters.filter(character=>character.trim()).length||1,perCharacter=Math.min(intensity,Math.floor(Math.max(0,2e3-text.length)/letters));return characters.map(character=>{if(!character.trim())return character;for(var count=Math.ceil(random()*perCharacter),marks="",index=0;index<count;index++)marks+=ZALGO_MARKS[Math.floor(random()*ZALGO_MARKS.length)];return character+marks}).join("")}var text=unbound.commands.option.string({description:"TEXT_DESC",required:!0});return{start:function start(){unbound.commands.register({mock:{description:"MOCK_DESC",options:{text},execute:({text})=>mock(text)},upside:{description:"UPSIDE_DESC",options:{text},execute:({text})=>upsideDown(text)},zalgo:{description:"ZALGO_DESC",options:{text},execute:({text})=>zalgo(text)},smallcaps:{description:"SMALLCAPS_DESC",options:{text},execute:({text})=>smallCaps(text)}})},stop:function stop(){}}}();return this.__plugin;}})